import { PDFDocument, StandardFonts, rgb, PDFName, PDFArray } from 'pdf-lib';
import { BorrowRequest, User, Storage } from './storage'; 

// Fungsi untuk tukar YYYY-MM-DD kepada DD-MM-YYYY
function formatDate(dateStr: string): string {
  if (!dateStr) return '';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length === 3) {
    const [year, month, day] = parts;
    return `${day}-${month}-${year}`; 
  }
  return dateStr; 
}

// Fungsi untuk ambil nama depan sahaja sebelum 'bin' or 'binti'
function getShortName(fullName: string): string {
  if (!fullName) return '';
  const parts = fullName.split(/\s+(?:bin|binti)\s+/i);
  return parts[0].trim();
}

function base64ToArrayBuffer(base64: string): ArrayBuffer {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

// 📦 Fungsi pembantu untuk memecah array item kepada kumpulan bersaiz 10
const chunkItems = (items: any[], size: number) => {
  const chunks = [];
  for (let i = 0; i < items.length; i += size) {
    chunks.push(items.slice(i, i + size));
  }
  return chunks;
};

export async function printBorangKEWPA9(req: BorrowRequest, currentUser: User, allUsers: User[]) {
  try {
    // ─── ⚠️ MASUKKAN STRING BASE64 TEMPLATE 10 LIST BARU ANDA DI SINI ───
    
    const b64Data = ""
 // <-- Letakkan kod teks Base64 baru anda di sini
    const existingPdfBytes = base64ToArrayBuffer(b64Data);

    const pdfDoc = await PDFDocument.load(existingPdfBytes);
    let pages = pdfDoc.getPages();
    const firstPage = pages[0]; 
    const { width, height } = firstPage.getSize(); 

    // FIX: Selesaikan isu 'Contents.push is not a function'
    const pageNode = firstPage.node as any;
    if (pageNode.Contents()) {
      const contentsKey = PDFName.of('Contents');
      const Contents = pageNode.get(contentsKey);
      if (Contents && !(Contents instanceof PDFArray)) {
        const array = pdfDoc.context.obj([Contents]);
        pageNode.set(contentsKey, array);
      }
    }

    const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
    const fontSize = 10;

    // ✨ Penunjuk halaman diposisikan secara boleh ubah (Dinamik)
    let currentPage = firstPage;

    const draw = (text: string, x: number, y: number, size = fontSize) => {
      if (!text) return;
      currentPage.drawText(text, { x, y: height - y, size, font, color: rgb(0, 0, 0) });
    };

    const requester = allUsers.find(u => u.uid === req.userId) || currentUser;
    const allAssets = await Storage.getAssets().catch(() => []);

    // Pecahkan item permohonan kepada kumpulan 10 item setiap helaian
    const itemsList = req.items && req.items.length > 0 ? req.items : [];
    const itemChunks = itemsList.length > 0 ? chunkItems(itemsList, 10) : [[]];

    // 🔥 FIX UTAMA: Klon halaman siap-siap SEBELUM melukis apa-apa supaya semuanya kekal bersih!
    for (let i = 1; i < itemChunks.length; i++) {
      const [copiedPage] = await pdfDoc.copyPages(pdfDoc, [0]);
      pdfDoc.addPage(copiedPage);
    }
    
    // Ambil senarai penuh halaman yang dilonjakkan (Semua dah clean & ready)
    const allPages = pdfDoc.getPages();

    // ─── 🔄 LOOP PROSES PEMBINAAN HALAMAN BORANG ─────────────────────────────
    for (let pageIndex = 0; pageIndex < itemChunks.length; pageIndex++) {
      
      // Pilih halaman bersih mengikut urutan index loop
      currentPage = allPages[pageIndex]; 

      // Optional: Cetak label petunjuk mukasurat di hujung atas borang
      if (itemChunks.length > 1) {
        draw(`Muka Surat: ${pageIndex + 1} / ${itemChunks.length}`, 480, 40, 8);
      }

      // ─── MAKLUMAT PEMOHON (Dicetak bersih pada setiap helaian borang) ───
      draw(getShortName(req.userName || ''), 161, 240);
      draw(req.purpose || '', 400, 240);                           
      draw((requester as any).jawatan || '', 161, 260);            
      draw((req as any).location || req.userDept || '', 400, 260);   
      draw(req.userDept || '', 161, 280);                          
      
      if (currentUser.role === 'admin') {
        draw(currentUser.name || '', 400, 280);                    
      }

      // ─── JADUAL ASET (Hanya memproses 10 item khusus chunk halaman semasa) ───
      const startY = 370;   
      const rowHeight = 20; 
      const currentChunk = itemChunks[pageIndex];

      currentChunk.forEach((item, index) => {
        const yPos = startY + (index * rowHeight);
        
        const matchedAsset = allAssets.find((a: any) => a.assetId === item.assetId);
        const namaKategori = matchedAsset?.category || item.assetName || ''; 
        
        // Kiraan nombor Bil kumulatif yang betul (Page 1: 1-10, Page 2: 11-20)
        const realBilNumber = (pageIndex * 10) + index + 1;
        
        draw(realBilNumber.toString(), 80, yPos);             
        draw(item.assignedSerialNumber || item.assignedAssetTag || '................', 95, yPos);  
        draw(namaKategori, 159, yPos);
        draw(formatDate(req.borrowDate || ''), 237, yPos);    
        draw(formatDate(req.returnDate || ''), 295, yPos);    
        
        const statusText = item.status === 'approved' ? 'Lulus' : item.status === 'rejected' ? 'Gagal' : '';
        draw(statusText, 360, yPos); 
      });

      // ─── RUANGAN TANDATANGAN (Dicetak bersih pada setiap helaian borang) ───
      const namaY = 627;
      const jawatanY = 640;
      const tarikhY = 654;
      
      // Blok Peminjam (Kiri)
      draw(req.userName || '', 117, namaY);                     
      draw((requester as any).jawatan || '', 117, jawatanY);       
      draw(formatDate(req.borrowDate || ''), 117, tarikhY);

      // Blok Pelulus (Kanan)
      if (currentUser.role === 'admin') {
        draw(currentUser.name || '', 400, namaY);               
        draw((currentUser as any).jawatan || '', 400, jawatanY);   
        draw(formatDate(req.borrowDate || ''), 400, tarikhY);
      }
    }
    // ─────────────────────────────────────────────────────────────────────────
    
    // 3. Proses Muat Turun Fail PDF Akhir
    const pdfBytes = await pdfDoc.save();
    const blob = new Blob([pdfBytes as any], { type: 'application/pdf' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `KEW-PA9-${req.requestId}.pdf`;
    link.click();

  } catch (error) {
    console.error("Ralat janaan PDF:", error);
    alert("Gagal memproses fail templat data.");
  }
}